import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define BLOCK_SIZE 256

__global__ void triplet_margin_loss_kernel(
    const float* __restrict__ anchor,
    const float* __restrict__ positive,
    const float* __restrict__ negative,
    float* __restrict__ loss_sum,
    int batch_size,
    int dim,
    float margin)
{
    int row = blockIdx.x;
    if (row >= batch_size) return;

    const float* a = anchor + (size_t)row * dim;
    const float* p = positive + (size_t)row * dim;
    const float* n = negative + (size_t)row * dim;

    float sum_pos = 0.0f;
    float sum_neg = 0.0f;

    for (int i = threadIdx.x; i < dim; i += blockDim.x) {
        float av = a[i];
        float da = av - p[i];
        float dn = av - n[i];
        sum_pos += da * da;
        sum_neg += dn * dn;
    }

    __shared__ float spos[BLOCK_SIZE];
    __shared__ float sneg[BLOCK_SIZE];

    spos[threadIdx.x] = sum_pos;
    sneg[threadIdx.x] = sum_neg;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            spos[threadIdx.x] += spos[threadIdx.x + s];
            sneg[threadIdx.x] += sneg[threadIdx.x + s];
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        float dist_pos = sqrtf(spos[0]);
        float dist_neg = sqrtf(sneg[0]);
        float l = dist_pos - dist_neg + margin;
        l = l > 0.0f ? l : 0.0f;
        atomicAdd(loss_sum, l);
    }
}

torch::Tensor triplet_margin_loss_cuda(
    torch::Tensor anchor,
    torch::Tensor positive,
    torch::Tensor negative,
    double margin)
{
    TORCH_CHECK(anchor.is_cuda(), "anchor must be a CUDA tensor");
    TORCH_CHECK(positive.is_cuda(), "positive must be a CUDA tensor");
    TORCH_CHECK(negative.is_cuda(), "negative must be a CUDA tensor");

    anchor = anchor.contiguous();
    positive = positive.contiguous();
    negative = negative.contiguous();

    int batch_size = anchor.size(0);
    int dim = anchor.size(1);

    auto loss_sum = torch::zeros({1}, anchor.options());

    dim3 grid(batch_size);
    dim3 block(BLOCK_SIZE);

    triplet_margin_loss_kernel<<<grid, block>>>(
        anchor.data_ptr<float>(),
        positive.data_ptr<float>(),
        negative.data_ptr<float>(),
        loss_sum.data_ptr<float>(),
        batch_size,
        dim,
        static_cast<float>(margin)
    );

    auto mean_loss = loss_sum / static_cast<double>(batch_size);
    return mean_loss.squeeze();
}
"""

cpp_source = r"""
torch::Tensor triplet_margin_loss_cuda(
    torch::Tensor anchor,
    torch::Tensor positive,
    torch::Tensor negative,
    double margin);
"""

triplet_module = load_inline(
    name="triplet_margin_loss_module",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["triplet_margin_loss_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that computes Triplet Margin Loss using a custom fused CUDA kernel.
    """
    def __init__(self, margin=1.0):
        super(ModelNew, self).__init__()
        self.margin = margin

    def forward(self, anchor, positive, negative):
        return triplet_module.triplet_margin_loss_cuda(
            anchor, positive, negative, self.margin
        )


def get_inputs():
    batch_size = 32768
    input_shape = (8192,)
    scale = torch.rand(())
    return [
        torch.rand(batch_size, *input_shape).cuda() * scale,
        torch.rand(batch_size, *input_shape).cuda(),
        torch.rand(batch_size, *input_shape).cuda(),
    ]


def get_init_inputs():
    return [1.0]

